// The compiled School Pack (spec §8.2 L1, §9.2): compact markdown with K ids, generated by code on
// publish and stored in `school_packs.compiled_prompt`. It sits behind the second cache breakpoint
// for every applicant to the school, so the output is deterministic: the same pack and cycle compile
// byte-for-byte identically. Nothing here reads the clock, iterates an unordered collection, or
// formats a number by locale.
//
// What is left out, and why (each listed in `excluded` with a reason, for the admin preview):
//   - `unverified`: `verified_at` is null (a draft). Nothing unverified reaches a user (§0).
//   - `unsourced`: no source at all. Every school fact shown to a user carries one (§0).
//   - `third_party_only`: every source is `third_party_reference` and no admin has approved a
//     rewrite in Admitstory's own words (§9.6). Third-party sources are also never named in the
//     index, so the UI can't show them.
//   - `future_dated`: verified after `now`, which only bad data produces.
//   - `stale_specific`: a course, centre, club or event verified before the current cycle. These
//     are exactly the "why school" specifics §9.3 withholds until re-verified. Other stale items
//     stay in, marked `stale`, as background the model may use but not cite (see freshness.ts).
//   - `parent_excluded`: a note under a prompt, round or record that was itself left out.

import { estimateTokens } from "@admitstory/shared";
import { isCitableSpecific, isStale } from "./freshness";
import type {
  CitedThing,
  EssayPrompt,
  IsoDate,
  KbSourceType,
  PackCited,
  PackItem,
  PackSource,
  PromptLimit,
  SchoolPack,
} from "./types";

export const PACK_TOKEN_TARGET = { min: 4_000, max: 10_000 } as const;

export type ExclusionReason =
  | "unverified"
  | "unsourced"
  | "third_party_only"
  | "future_dated"
  | "stale_specific"
  | "parent_excluded";

export interface PackIndexEntry {
  /** What the K id stands for, as compiled (without the id and the source tag). */
  text: string;
  /** Citable sources only: `third_party_reference` ids are never listed. */
  sourceIds: string[];
  verifiedAt: IsoDate;
  /** Top-level section, e.g. `application`, `academics`. */
  section: string;
  /** Best source type, or null for an admin-approved rewrite of third-party notes. */
  sourceType: KbSourceType | null;
  /** Verified before the current cycle: background only, never a cited specific. */
  stale: boolean;
}

export interface CompiledPack {
  text: string;
  tokenCount: number;
  /** K id → entry, in compiled order. Only what the text contains can be cited. */
  itemIndex: Record<string, PackIndexEntry>;
  excluded: { id: string; section: string; reason: ExclusionReason }[];
}

export interface CompilePackOptions {
  /** The current application cycle, e.g. "2026-27". Decides staleness. */
  cycle: string;
  /** Only used to reject future-dated verifications; never appears in the output. */
  now: Date | IsoDate;
  /** Overrides freshness.ts's CYCLE_OPENS_ON ("MM-DD"). */
  cycleOpensOn?: string;
}

/* Formatting ------------------------------------------------------------------------------------ */

/** 175000 → "175,000", independent of the host's locale. */
function thousands(value: number): string {
  const [whole = "0", fraction] = String(value).split(".");
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return fraction ? `${grouped}.${fraction}` : grouped;
}

function percent(share: number): string {
  return `${Math.round(share * 1000) / 10}%`;
}

const LIMIT_UNITS: Record<PromptLimit["kind"], string> = {
  words: "words",
  chars_incl_spaces: "chars incl. spaces",
  chars_excl_spaces: "chars excl. spaces",
};

function limitText(limit: PromptLimit): string {
  return `${limit.value} ${LIMIT_UNITS[limit.kind]}`;
}

function quote(text: string): string {
  return JSON.stringify(text);
}

/* The compiler ---------------------------------------------------------------------------------- */

interface Context {
  sources: Map<string, PackSource>;
  cycle: string;
  today: IsoDate;
  opensOn: string | undefined;
  lines: string[];
  index: Record<string, PackIndexEntry>;
  excluded: CompiledPack["excluded"];
}

type Verdict =
  | { ok: true; sourceIds: string[]; sourceType: KbSourceType | null; stale: boolean }
  | { ok: false; reason: ExclusionReason };

function judge(
  ctx: Context,
  node: PackCited & { approved_rewrite?: boolean },
  specific: boolean,
): Verdict {
  if (node.verified_at === null) return { ok: false, reason: "unverified" };
  if (node.verified_at > ctx.today) return { ok: false, reason: "future_dated" };
  const known = node.source_ids
    .map((id) => ctx.sources.get(id))
    .filter((s): s is PackSource => s !== undefined);
  if (known.length === 0) return { ok: false, reason: "unsourced" };
  const citable = known.filter((s) => s.type !== "third_party_reference");
  if (citable.length === 0 && node.approved_rewrite !== true)
    return { ok: false, reason: "third_party_only" };
  const stale = isStale(node.verified_at, ctx.cycle, ctx.opensOn);
  if (stale && specific) return { ok: false, reason: "stale_specific" };
  // Highest trust first; ties keep the order the sources are cited in.
  const best = [...citable].sort((a, b) => b.trust - a.trust)[0];
  return {
    ok: true,
    sourceIds: citable.map((s) => s.id),
    sourceType: best?.type ?? null,
    stale,
  };
}

function tag(verdict: Extract<Verdict, { ok: true }>, verifiedAt: IsoDate): string {
  const type = verdict.sourceType ?? "admitstory";
  return verdict.stale ? `[${type} ${verifiedAt} stale]` : `[${type} ${verifiedAt}]`;
}

/**
 * Emit one cited line (`K12 text [official 2026-08-14]`) if the node passes, and record it in the
 * index. Returns whether it was emitted, so callers can drop a record's children with it.
 */
function emit(
  ctx: Context,
  node: PackCited & { approved_rewrite?: boolean },
  section: string,
  text: string,
  options: { indent?: string; specific?: boolean; parentOk?: boolean } = {},
): boolean {
  if (options.parentOk === false) {
    ctx.excluded.push({ id: node.id, section, reason: "parent_excluded" });
    return false;
  }
  const verdict = judge(ctx, node, options.specific ?? false);
  if (!verdict.ok) {
    ctx.excluded.push({ id: node.id, section, reason: verdict.reason });
    return false;
  }
  // `judge` only passes nodes with a verified date.
  const verifiedAt = node.verified_at as IsoDate;
  ctx.lines.push(`${options.indent ?? ""}${node.id} ${text} ${tag(verdict, verifiedAt)}`);
  ctx.index[node.id] = {
    text,
    sourceIds: verdict.sourceIds,
    verifiedAt,
    section,
    sourceType: verdict.sourceType,
    stale: verdict.stale,
  };
  return true;
}

function items(
  ctx: Context,
  list: readonly PackItem[],
  section: string,
  indent = "",
  parentOk = true,
): void {
  for (const item of list) emit(ctx, item, section, item.text, { indent, parentOk });
}

/** A heading, then the body; the heading is removed again if the body emitted nothing. */
function block(ctx: Context, heading: string, body: () => void): void {
  const at = ctx.lines.length;
  ctx.lines.push(heading);
  body();
  if (ctx.lines.length === at + 1) ctx.lines.pop();
}

function prompts(ctx: Context, list: readonly EssayPrompt[]): void {
  for (const prompt of list) {
    const head = [
      prompt.key,
      prompt.required ? "required" : "optional",
      prompt.list_count
        ? `list of ${prompt.list_count}, ${limitText(prompt.limit)} each`
        : limitText(prompt.limit),
      prompt.archetypes.join(",") || "—",
    ].join(" | ");
    // A prompt without verified verbatim wording can't be written to.
    const ok =
      prompt.prompt_verbatim !== null &&
      emit(ctx, prompt, "application", `${head}\n  prompt: ${quote(prompt.prompt_verbatim)}`);
    if (prompt.prompt_verbatim === null)
      ctx.excluded.push({ id: prompt.id, section: "application", reason: "unverified" });
    if (ok && prompt.parts.length > 0) ctx.lines.push(`  parts: ${prompt.parts.join("; ")}`);
    items(ctx, prompt.notes, "application", "  ", ok);
  }
}

function things(ctx: Context, label: string, list: readonly CitedThing[], section: string): void {
  block(ctx, `${label}:`, () => {
    for (const thing of list) {
      const forWhat =
        thing.why_it_matters_for.length > 0 ? ` | for: ${thing.why_it_matters_for.join(", ")}` : "";
      emit(ctx, thing, section, `${thing.name}: ${thing.what_it_is}${forWhat}`, {
        specific: true,
      });
    }
  });
}

function joinOrDash(values: readonly string[]): string {
  return values.length > 0 ? values.join(", ") : "—";
}

export function compilePack(pack: SchoolPack, options: CompilePackOptions): CompiledPack {
  const today =
    typeof options.now === "string"
      ? options.now.slice(0, 10)
      : options.now.toISOString().slice(0, 10);
  const ctx: Context = {
    sources: new Map(pack.sources.map((s) => [s.id, s] as const)),
    cycle: options.cycle,
    today,
    opensOn: options.cycleOpensOn,
    lines: [],
    index: {},
    excluded: [],
  };
  const { school, application: app } = pack;

  ctx.lines.push(
    `SCHOOL PACK  ${school.short_name} | ${school.name} | ${school.city}, ${school.country} | full-time MBA | cycle ${pack.cycle} | v${pack.version}`,
    "Cite items by K id. [type date] = strongest source type and the date it was verified. " +
      "Items marked stale were verified before this cycle: background only, never cite them as school specifics.",
  );

  block(ctx, "\nROUNDS", () => {
    for (const round of pack.rounds) {
      const parts = [round.name, `deadline ${round.deadline}`];
      if (round.decision_date) parts.push(`decision ${round.decision_date}`);
      if (round.interview_invites_window) parts.push(`invites ${round.interview_invites_window}`);
      const ok = emit(ctx, round, "rounds", parts.join(" | "));
      items(ctx, round.notes, "rounds", "  ", ok);
    }
  });

  block(ctx, "\nESSAYS", () => prompts(ctx, app.essays));
  block(ctx, "\nSHORT ANSWERS", () => prompts(ctx, app.short_answers));
  block(ctx, "\nGOAL FIELDS", () => prompts(ctx, app.goal_fields));
  block(ctx, "\nOPTIONAL ESSAY", () =>
    prompts(ctx, app.optional_essay ? [app.optional_essay] : []),
  );
  block(ctx, "\nREAPPLICANTS", () => {
    if (!app.reapplicant) return;
    prompts(ctx, app.reapplicant.essay ? [app.reapplicant.essay] : []);
    items(ctx, app.reapplicant.policy, "application");
  });

  block(ctx, "\nVIDEO", () => {
    for (const video of app.video) {
      const parts = [video.format.replace("_", " ")];
      if (video.think_time_s !== null) parts.push(`think ${video.think_time_s}s`);
      if (video.answer_time_s !== null) parts.push(`answer ${video.answer_time_s}s`);
      if (video.attempts !== null) parts.push(`attempts ${video.attempts}`);
      parts.push(video.scripting_allowed ? "scripting allowed" : "no scripting");
      const ok = emit(ctx, video, "application", parts.join(" | "));
      items(ctx, video.question_types, "application", "  ", ok);
    }
  });

  block(ctx, "\nFORM", () => {
    for (const section of app.form_sections) {
      const parts = [section.key, quote(section.label)];
      if (section.item_count_max) parts.push(`max ${section.item_count_max} items`);
      // Without a counting rule the line stays as it was, so published packs compile unchanged.
      if (section.char_limit)
        parts.push(
          section.limit_kind
            ? limitText({ kind: section.limit_kind, value: section.char_limit })
            : `${section.char_limit} chars`,
        );
      const ok = emit(ctx, section, "application", parts.join(" | "));
      items(ctx, section.guidance, "application", "  ", ok);
    }
  });

  block(ctx, "\nRECOMMENDATIONS", () => {
    const recs = app.recommendations;
    if (!recs) return;
    const questions = recs.questions
      .map((q) => `\n  q: ${quote(q.text_verbatim)}${q.limit ? ` (${limitText(q.limit)})` : ""}`)
      .join("");
    const ok = emit(ctx, recs, "application", `${recs.count} | ${recs.format}${questions}`);
    items(ctx, recs.notes, "application", "  ", ok);
  });

  block(ctx, "\nRESUME", () => {
    if (!app.resume) return;
    const ok = emit(ctx, app.resume, "application", `${app.resume.page_limit} page max`);
    items(ctx, app.resume.notes, "application", "  ", ok);
  });

  block(ctx, "\nTEST POLICY", () => items(ctx, app.test_policy, "application"));
  block(ctx, "\nFEES AND WAIVERS", () => items(ctx, app.fees_waivers, "application"));

  block(ctx, "\nVALUES", () => {
    items(ctx, pack.values.stated, "values");
    for (const entry of pack.values.trait_map) {
      const line = `${quote(entry.school_value)} -> ${joinOrDash(entry.admitstory_traits)}`;
      if (entry.note) emit(ctx, entry.note, "values", `trait map: ${line} | ${entry.note.text}`);
      else ctx.lines.push(`trait map: ${line}`);
    }
  });

  block(ctx, "\nCULTURE AND LOCATION", () =>
    items(ctx, pack.culture_and_location, "culture_and_location"),
  );

  block(ctx, "\nACADEMICS", () => {
    things(ctx, "courses", pack.academics.courses, "academics");
    things(ctx, "centres", pack.academics.centers, "academics");
    things(ctx, "experiential", pack.academics.experiential, "academics");
    block(ctx, "structure:", () => items(ctx, pack.academics.structure, "academics"));
  });

  block(ctx, "\nCOMMUNITY", () => {
    things(ctx, "clubs", pack.community.clubs, "community");
    things(ctx, "treks and events", pack.community.treks_events, "community");
    block(ctx, "traditions:", () => items(ctx, pack.community.traditions, "community"));
  });

  block(ctx, "\nCAREERS", () => {
    const report = pack.careers.employment_report;
    if (report) {
      const functions = report.by_function
        .map(
          (f) =>
            `${f.function} ${percent(f.share)}${f.median_base !== null ? ` median ${report.currency} ${thousands(f.median_base)}` : ""}`,
        )
        .join("; ");
      const employers =
        report.top_employers.length > 0
          ? ` | top employers: ${report.top_employers.join(", ")}`
          : "";
      const ok = emit(
        ctx,
        report,
        "careers",
        `employment report, class of ${report.class_year}: ${functions}${employers}`,
      );
      if (report.intl_offer_rates)
        emit(ctx, report.intl_offer_rates, "careers", report.intl_offer_rates.text, {
          indent: "  ",
          parentOk: ok,
        });
    }
    items(ctx, pack.careers.recruiting_notes, "careers");
  });

  block(ctx, "\nCLASS PROFILE", () => {
    const profile = pack.class_profile;
    if (!profile) return;
    const parts = [`class of ${profile.class_year}`];
    if (profile.class_size !== null) parts.push(`size ${thousands(profile.class_size)}`);
    if (profile.gmat_focus_median !== null)
      parts.push(`GMAT Focus median ${profile.gmat_focus_median}`);
    if (profile.gmat_classic_median !== null)
      parts.push(`GMAT median ${profile.gmat_classic_median}`);
    if (profile.gre_median)
      parts.push(`GRE median V${profile.gre_median.verbal} Q${profile.gre_median.quant}`);
    if (profile.gpa_median !== null)
      parts.push(
        `GPA median ${profile.gpa_median}${profile.gpa_scale !== null ? `/${profile.gpa_scale}` : ""}`,
      );
    if (profile.work_experience_years_median !== null)
      parts.push(`work experience median ${profile.work_experience_years_median} yrs`);
    if (profile.international_share !== null)
      parts.push(`international ${percent(profile.international_share)}`);
    emit(ctx, profile, "class_profile", parts.join(" | "));
  });

  block(ctx, "\nINTERVIEW", () => {
    const interview = pack.interview;
    if (!interview) return;
    const blind =
      interview.blind === null ? "blind: unknown" : interview.blind ? "blind" : "file-read";
    const ok = emit(
      ctx,
      interview,
      "interview",
      [
        interview.invitation.replaceAll("_", " "),
        `by ${joinOrDash(interview.who)}`,
        blind,
        `${interview.length_min} min`,
        joinOrDash(interview.location),
      ].join(" | "),
    );
    for (const question of interview.common_questions)
      emit(ctx, question, "interview", `(w${question.frequency_weight}) ${quote(question.text)}`, {
        indent: "  ",
        parentOk: ok,
      });
    items(ctx, interview.format_notes, "interview", "  ", ok);
  });

  block(ctx, "\nAI POLICY", () => {
    const policy = pack.ai_policy;
    const parts = [policy.stance, `applies to ${joinOrDash(policy.applies_to)}`];
    if (policy.disclosure_text) parts.push(`disclosure: ${quote(policy.disclosure_text)}`);
    const ok = emit(ctx, policy, "ai_policy", parts.join(" | "));
    items(ctx, policy.notes, "ai_policy", "  ", ok);
  });

  block(ctx, "\nSCHOLARSHIPS", () => items(ctx, pack.scholarships, "scholarships"));
  block(ctx, "\nINSIDER NOTES", () => items(ctx, pack.insider_notes, "insider_notes"));
  block(ctx, "\nAVOID", () => items(ctx, pack.avoid, "avoid"));
  block(ctx, "\nANGLES THAT WORK", () => items(ctx, pack.angles_that_work, "angles_that_work"));
  block(ctx, "\nGLOSSARY", () => {
    for (const entry of pack.glossary)
      emit(ctx, entry, "glossary", `${entry.term}: ${entry.plain_definition}`);
  });

  const text = `${ctx.lines.join("\n")}\n`;
  return { text, tokenCount: estimateTokens(text), itemIndex: ctx.index, excluded: ctx.excluded };
}

/**
 * The K ids a user-facing why-school sentence may cite: compiled, verified this cycle, and backed
 * by a source the user can be shown (see `isCitableSpecific`).
 */
export function citableSpecificIds(compiled: Pick<CompiledPack, "itemIndex">): string[] {
  return Object.entries(compiled.itemIndex)
    .filter(([, entry]) => isCitableSpecific(entry))
    .map(([id]) => id);
}
